/**
 * Locally bundled audio.
 *
 * The deployment ships the whole curated corpus compacted to WebM/Opus under
 * `/public/audio/{clipId}.webm` (generated by `scripts/bundle-audio.mjs`), so a
 * lesson needs no third-party service at all: every voice is a static asset of
 * this app, cached immutably by the browser and the edge, and playable offline
 * on first visit.
 *
 * This module is the single place that knows how a clip id maps onto a bundled
 * file. Resolution order everywhere is: bundled file → IndexedDB cache →
 * dataset server — each step a graceful fallback, so a trimmed or partially
 * bundled build (and the pre-bundle development state) keeps working exactly
 * like before.
 */

import bundleStats from '../data/audio-bundle.json';

/**
 * True when this build ships the corpus locally under `/public/audio`.
 *
 * Derived from the stats file `scripts/bundle-audio.mjs` writes, so a checkout
 * that has not run the bundler (or has had the audio stripped) automatically
 * falls back to the dataset-server path end to end — resolution, the Settings
 * panel, and background pool growth all key off this single flag.
 */
export const BUNDLED_AUDIO = bundleStats.clips > 0;

/** What the bundle contains, for the Settings readout. */
export const BUNDLED_AUDIO_STATS: { clips: number; bytes: number } = {
  clips: bundleStats.clips,
  bytes: bundleStats.bytes,
};

/** Public URL for a bundled clip. */
export function bundledAudioPath(id: string): string {
  return `/audio/${encodeURIComponent(id)}.webm`;
}

/**
 * Fetches a bundled clip as a same-origin `audio/webm` Blob, or null when the
 * id has no bundled file. Never throws: a missing asset simply moves the caller
 * on to the next resolution layer.
 */
export async function fetchBundledAudio(id: string, signal?: AbortSignal): Promise<Blob | null> {
  if (!BUNDLED_AUDIO) return null;
  try {
    const response = await fetch(bundledAudioPath(id), { signal, cache: 'default' });
    if (!response.ok) return null;
    const buffer = await response.arrayBuffer();
    // A truncation or an HTML error page must never masquerade as audio.
    if (buffer.byteLength < 512) return null;
    return new Blob([buffer], { type: 'audio/webm' });
  } catch {
    return null;
  }
}
